
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_kgg99_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_kgg99", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.083324951508860e+00, -4.007755992942958e+00, -3.902012620781295e+00, -3.755838599691623e+00, -3.557298057062543e+00, -3.294383292134096e+00, -2.958682036251068e+00, -2.551679368773390e+00, -2.091762390480394e+00, -1.610164101831608e+00, -1.105294856041843e+00, -6.786954757709849e-01, -5.685970968686748e-01, -4.806383817413680e-01, -3.646980184315063e-01, -2.535358644585038e-01, -1.691832547051835e-01, -1.124014673465912e-01, 3.029838495164152e-04, 3.405208162843802e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


